package constants;

/**
 * He co so ho tro: nhi phan, thap phan, thap luc phan.
 * Moi he giu so nguoi dung chon o menu, co so (2, 10, 16) va nhan in ra man hinh.
 *
 * @author CuongThai Academy
 */
public enum Base {

    // Nhi phan: chon 1, co so 2
    BINARY(1, 2, "BIN"),

    // Thap phan: chon 2, co so 10
    DECIMAL(2, 10, "DEC"),

    // Thap luc phan: chon 3, co so 16
    HEXADECIMAL(3, 16, "HEX");

    // So nguoi dung chon o menu
    private int menuChoice;

    // Co so (2, 10, 16)
    private int radix;

    // Nhan in ra man hinh (BIN, DEC, HEX)
    private String label;

    // Constructor cua enum: gan so chon, co so, nhan
    private Base(int menuChoice, int radix, String label) {
        this.menuChoice = menuChoice;
        this.radix = radix;
        this.label = label;
    }

    // Lay co so
    public int getRadix() {
        return radix;
    }

    // Lay nhan
    public String getLabel() {
        return label;
    }

    // Lay cac chu so hop le cua he (vd he 2 -> "01")
    public String getAllowedDigits() {
        return Constants.DIGITS.substring(0, radix);
    }

    // Tim he co so theo so nguoi dung chon; khong co thi tra null
    public static Base findByChoice(int choice) {
        // Duyet tung he, trung so chon thi tra ve he do
        for (Base base : values()) {
            // So chon khop thi day la he can tim
            if (base.menuChoice == choice) {
                return base;
            }
        }

        return null;
    }
}

package constants;

/**
 * Hang so dung chung: lua chon menu, bang chu so, dau am/duong.
 *
 * @author CuongThai Academy
 */
public final class Constants {


    // Chon 0 o menu dau vao la thoat
    public static final int MENU_EXIT = 0;

    // Lua chon he co so nho nhat
    public static final int BASE_MIN = 1;

    // Lua chon he co so lon nhat
    public static final int BASE_MAX = 3;

    // Bang chu so: vi tri trong chuoi = gia tri chu so (A = 10 ... F = 15)
    public static final String DIGITS = "0123456789ABCDEF";

    // Dau am o dau gia tri
    public static final String MINUS = "-";

    // Dau duong o dau gia tri
    public static final String PLUS = "+";

    // Ket qua khi gia tri bang 0
    public static final String ZERO = "0";

    // Constructor private: lop chi chua hang so, khong cho tao doi tuong
    private Constants() {
    }
}

package constants;

/**
 * Moi cau chu in ra man hinh: menu, cau nhac nhap, ket qua, thong bao loi.
 *
 * @author CuongThai Academy
 */
public final class Message {


    // Menu chinh: chon he co so dau vao, 0 de thoat
    public static final String MENU
            = "======= CHANGE BASE NUMBER SYSTEM =======\n"
            + "1. Binary (base 2)\n"
            + "2. Decimal (base 10)\n"
            + "3. Hexadecimal (base 16)\n"
            + "0. Exit\n"
            + "=========================================";

    // Nhac chon he co so dau vao
    public static final String INPUT_BASE_IN = "Choose the INPUT base: ";

    // Nhac chon he co so dau ra
    public static final String INPUT_BASE_OUT = "Choose the OUTPUT base: ";

    // Nhac nhap gia tri can doi
    public static final String INPUT_VALUE = "Enter the input value: ";

    // Loi: go chu hoac de trong o cho phai nhap so nguyen
    public static final String INVALID_NUMBER
            = "Ban phai nhap 1 so nguyen (vi du: 1, 2, 3), khong nhap chu hay de trong. "
