/**
 * Diem bat dau: hien menu, nhap va kiem du lieu, goi Controller doi he (1 lan moi luot).
 *
 * @author CuongThai Academy
 */
public final class Main {

    // Constructor private: lop chi co ham static
    private Main() {
    }

    // Ham chay chuong trinh: lap menu den khi chon 0
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        ConvertController convertController = new ConvertController();
        ConvertRequestDTO convertRequestDTO = null;
        int inputChoice = 0;

        // Lap lai cho den khi nguoi dung chon 0
        while (true) {
            System.out.println(Message.MENU);
            inputChoice = promptInputBase(scanner);

            // Chon 0 thi chao va thoat
            if (inputChoice == Constants.MENU_EXIT) {
                System.out.println(Message.GOODBYE);
                return;
            }

            // Tao phieu nhap: he vao, he ra, gia tri can doi
            convertRequestDTO = new ConvertRequestDTO();
            convertRequestDTO.setInputBase(Base.findByChoice(inputChoice));
            convertRequestDTO.setOutputBase(Base.findByChoice(promptOutputBase(scanner)));
            convertRequestDTO.setValue(promptValue(scanner));

            // Kiem chu so dung he roi doi; sai thi in loi va ve menu
            try {
                Validation.checkValue(convertRequestDTO.getValue(),
                        convertRequestDTO.getInputBase());
                convertController.convert(convertRequestDTO);
            } catch (Exception e) {
                // Sai chu so hoac so qua lon: in loi roi ve menu
                System.out.println(e.getMessage());
            }
        }
    }

    // Hoi he vao (0 den 3, 0 la thoat) den khi hop le
    private static int promptInputBase(Scanner scanner) {
        // Lap den khi nhap dung
        while (true) {
            System.out.print(Message.INPUT_BASE_IN);

            // Kiem lua chon trong khoang 0..3
            try {
                return Validation.getChoice(scanner.nextLine(), Constants.MENU_EXIT,
                        Constants.BASE_MAX);
            } catch (Exception e) {
                // In loi roi hoi lai
                System.out.println(e.getMessage());
            }
        }
    }

    // Hoi he ra (1 den 3) den khi hop le
    private static int promptOutputBase(Scanner scanner) {
        // Lap den khi nhap dung
        while (true) {
            System.out.print(Message.INPUT_BASE_OUT);

            // Kiem lua chon trong khoang 1..3
            try {
                return Validation.getChoice(scanner.nextLine(), Constants.BASE_MIN,
                        Constants.BASE_MAX);
            } catch (Exception e) {
                // In loi roi hoi lai
                System.out.println(e.getMessage());
            }
        }
    }

    // Hoi gia tri can doi den khi khong rong
    private static String promptValue(Scanner scanner) {
        // Lap den khi nhap dung
        while (true) {
            System.out.print(Message.INPUT_VALUE);

            // Kiem gia tri khong rong
            try {
                return Validation.getValue(scanner.nextLine());
            } catch (Exception e) {
                // In loi roi hoi lai
                System.out.println(e.getMessage());
            }
        }
    }
}

